--- a/core/runtime/kernel_scheduler.cc
+++ b/core/runtime/kernel_scheduler.cc
@@ -210,6 +210,28 @@
+// fast-path: small token kernels go through priority queue to reduce head-of-line blocking
+if (is_small_kernel(job)) {
+  priority_queue_.push(job);
+  try_preempt_long_kernel();
+  return;
+}

--- a/core/runtime/kv_cache_hotpath.cc
+++ b/core/runtime/kv_cache_hotpath.cc
@@ -44,7 +44,26 @@
- std::lock_guard<std::mutex> lg(shard_mutex_);
- Value v = shard_lookup(key);
+ // lock-free fast-path reads: use atomic pointer and read-copy if needed
+ auto ptr = shard_atomic_ptr_.load(std::memory_order_acquire);
+ if (likely(ptr && ptr->contains(key))) {
+  Value v = ptr->get_no_alloc(key, &scratch_buffer_);
+  return v;
+ }
+ // fallback to locked path
+ std::lock_guard<std::mutex> lg(shard_mutex_);
+ Value v = shard_lookup(key);

--- a/core/runtime/continuous_batcher.cc
+++ b/core/runtime/continuous_batcher.cc
@@ -80,6 +80,34 @@
+// adaptive flush: lower interval when queue-latency exceeds threshold for small batches
+if (queue_latency_ms > target_latency && pending_size < optimal_batch) {
+  flush_interval_ms = std::max(min_flush_ms, flush_interval_ms / 2);
+}
+// allow opportunistic partial flushes when latency SLOs degrade
+if (pending_size > 0 && estimated_latency > slo_ms * 0.8) {
+  flush();
+}
